    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '301: A "Thunderclap" headache (maximal intensity within seconds) is _____ until proven otherwise.', '["Migraine", "Subarachnoid Hemorrhage (SAH)", "Tension headache", "Sinusitis"]', 1, 'Often described as "the worst headache of my life."'),
    (v_topic_id, '302: "Headache" + "Jaw Claudication" (pain when chewing) + "Scalp Tenderness" in a 70-year-old is:', '["Tension headache", "Temporal (Giant Cell) Arteritis", "Trigeminal neuralgia", "Stroke"]', 1, 'A high-yield red flag; requires urgent steroids to prevent permanent blindness.'),
    (v_topic_id, '303: "Migraine" headaches are typically _____ and _____:', '["Bilateral; steady", "Unilateral; pulsating (often with nausea/photophobia)", "Bilateral; tight", "Sudden; tearing"]', 1, 'Usually lasts 4-72 hours.'),
    (v_topic_id, '304: "Tension-type" headaches are typically described as:', '["Pulsating and unilateral", "Bilateral, non-pulsating, \"band-like\" tightness", "Sudden onset", "Orbital"]', 1, 'The most common type of primary headache.'),
    (v_topic_id, '305: "Cluster" headaches occur more commonly in _____ and present as severe _____ pain.', '["Women; bilateral", "Men; unilateral periorbital (with lacrimation/rhinorrhea)", "Children; occipital", "Elderly; temporal"]', 1, 'They often occur in "clusters" of several weeks at the same time each day.'),
    (v_topic_id, '306: "Headache" that is "Worse when lying flat" and "Worse in the morning" suggests:', '["Migraine", "Increased Intracranial Pressure (e.g., Tumor or IIH)", "Tension headache", "Anxiety"]', 1, 'Intracranial pressure increases in the supine position.'),
    (v_topic_id, '307: "Papilledema" on fundoscopic exam is a hallmark sign of:', '["Glaucoma", "Increased Intracranial Pressure", "Diabetes", "Hypertension only"]', 1, 'It is the swelling of the optic disc due to pressure from behind.'),
    (v_topic_id, '308: "Trigeminal Neuralgia" presents as brief, "electric-shock-like" stabs of pain in the:', '["Forehead only", "Face (usually V2 or V3 distribution)", "Back of the head", "Shoulder"]', 1, 'Often triggered by light touch, chewing, or cold air.'),
    (v_topic_id, '309: "Acute Altered Mental Status" (Delirium) is distinguished from Dementia by its:', '["Gradual onset", "Acute/Subacute onset and fluctuating course with impaired attention", "Permanent nature", "Lack of hallucinations"]', 1, 'Delirium is usually a reversible response to an underlying medical illness.'),
    (v_topic_id, '310: A "Fever" in an elderly patient with "Confusion" should always prompt a search for:', '["Urinary Tract Infection (UTI) or Pneumonia", "Migraine", "Stroke", "Dementia"]', 0, 'Infections are the most common "System 1" cause of delirium in the elderly.'),
    (v_topic_id, '311: "Wernicke''s Encephalopathy" triad: Confusion, Ophthalmoplegia, and _____:', '["Fever", "Ataxia (unsteady gait)", "Tremor", "Seizure"]', 1, 'Caused by Thiamine (B1) deficiency, especially in alcoholics.'),
    (v_topic_id, '312: "Korsakoff Syndrome" is the chronic phase of B1 deficiency characterized by:', '["Blindness", "Anterograde/Retrograde Amnesia and Confabulation", "Paralysis", "Deafness"]', 1, 'The patient makes up stories (confabulation) to fill in the gaps in their memory.'),
    (v_topic_id, '313: "Stroke" (Ischemic or Hemorrhagic) typically presents with _____ neurological deficits.', '["Global", "Sudden-onset focal", "Gradual", "Symmetric"]', 1, 'Example: Unilateral weakness or speech difficulty.'),
    (v_topic_id, '314: "Transient Ischemic Attack" (TIA) is defined as neurological symptoms that resolve within:', '["5 minutes", "24 hours (with no evidence of infarction on MRI)", "1 week", "1 month"]', 1, 'TIA is a warning sign of a high risk for an impending stroke.'),
    (v_topic_id, '315: "Syncope" vs "Seizure": Which is more likely if the patient has a "Post-ictal period" of confusion?', '["Syncope", "Seizure", "Both are equal", "Neither"]', 1, 'Syncope usually has a rapid return to full consciousness.'),
    (v_topic_id, '316: "Generalized Tonic-Clonic" seizures are characterized by:', '["Staring spells only", "Loss of consciousness followed by stiffening (tonic) and jerking (clonic)", "Unilateral weakness", "Headache only"]', 1, 'Often accompanied by tongue biting and urinary incontinence.'),
    (v_topic_id, '317: "Absentee" (Absence) seizures in children present as:', '["Violent jerking", "Brief staring spells without loss of posture", "Falling down", "Sleep-walking"]', 1, 'ECG shows classic 3 Hz spike-and-wave discharges.'),
    (v_topic_id, '318: "Vertigo" is specifically defined as:', '["Feeling faint", "The sensation of spinning (the world or the patient)", "Blurred vision", "Weakness"]', 1, 'Indicates a problem in the vestibular system.'),
    (v_topic_id, '319: "Benign Paroxysmal Positional Vertigo" (BPPV) is triggered by:', '["Stress", "Changes in head position (e.g., rolling over in bed)", "Loud noises", "High salt intake"]', 1, 'Caused by otoliths (canaliths) in the semicircular canals.'),
    (v_topic_id, '320: "Dix-Hallpike Maneuver" is the diagnostic test for:', '["Menieres disease", "BPPV", "Stroke", "Brain tumor"]', 1, 'A positive test results in characteristic nystagmus.'),
    (v_topic_id, '321: "M\u00e9ni\u00e8re Disease" triad: Vertigo, Tinnitus, and _____:', '["Fever", "Fluctuating sensorineural hearing loss", "Headache", "Weakness"]', 1, 'Caused by excess endolymphatic fluid pressure.'),
    (v_topic_id, '322: "Peripheral" vertigo is usually _____ and associated with _____:', '["Mild; stroke", "Severe; hearing loss or tinnitus", "Permanent; blindness", "Painless; weakness"]', 1, 'Common causes include BPPV and vestibular neuritis.'),
    (v_topic_id, '323: "Central" vertigo (brainstem/cerebellar) is often associated with _____:', '["Normal hearing but other cranial nerve deficits or ataxia", "Severe ear pain", "Normal balance", "Fever"]', 0, 'Vertical nystagmus is a red flag for central vertigo.'),
    (v_topic_id, '324: "Fever of Unknown Origin" (FUO) is defined as a fever > 38.3\u00b0C on several occasions for at least:', '["3 days", "3 weeks (with 1 week of in-hospital investigation)", "3 months", "1 year"]', 1, 'Requires a systematic search for occult infection, malignancy, or connective tissue disease.'),
    (v_topic_id, '325: "Involuntary Weight Loss" is clinically significant if more than _____% of body weight is lost in _____ months.', '["1%; 1", "5%; 6 to 12", "10%; 24", "20%; 1"]', 1, 'Prompts a search for cancer (GI, lung, lymphoma), hyperthyroidism, or depression.'),
    (v_topic_id, '326: "Lymphadenopathy" that is "Hard," "Fixed," and "Non-tender" is highly concerning for:', '["Infection", "Malignancy (Metastatic)", "Normal nodes", "Allergy"]', 1, 'Inflammatory nodes are usually soft and tender.'),
    (v_topic_id, '327: "Supraclavicular" lymphadenopathy is _____:', '["Always benign", "Almost always pathologically significant (suggestive of malignancy)", "Common in children", "Normal"]', 1, 'Right supraclavicular = Lung/Mediastinum; Left supraclavicular (Virchow) = Abdominal.'),
    (v_topic_id, '328: "Generalized" lymphadenopathy (involving 3 or more non-contiguous areas) is common in:', '["Local infection", "Systemic infections (HIV, EBV) or Malignancy (Lymphoma/Leukemia)", "Trauma", "Anxiety"]', 1, 'Usually indicates a systemic process.'),
    (v_topic_id, '329: "Splenomegaly" + "Fever" + "Pharyngitis" + "Atypical Lymphocytes" =', '["Strep throat", "Infectious Mononucleosis (EBV)", "Lymphoma", "Acute Leukemia"]', 1, 'Avoid contact sports to prevent splenic rupture.'),
    (v_topic_id, '330: "Generalized Weakness" must be distinguished from "Focal Weakness." Focal weakness suggests:', '["Anemia", "Neurological lesion (nerve, root, cord, or brain)", "Dehydration", "Depression"]', 1, 'Example: Weakness limited to the right leg.'),
    (v_topic_id, '331: "Proximal Muscle Weakness" (difficulty rising from a chair or combing hair) suggests:', '["Myopathy (e.g., Polymyositis) or NMJ disorder", "Neuropathy (e.g., Diabetes)", "Anemia", "Stroke"]', 0, 'Neuropathies usually present with distal weakness (difficulty with fine tasks).'),
    (v_topic_id, '332: "Fatigue" that improves with rest but worsens throughout the day suggests:', '["Depression", "Myasthenia Gravis", "Anemia", "Heart failure"]', 1, 'Classic neuromuscular junction fatigue.'),
    (v_topic_id, '333: "Lower Motor Neuron" (LMN) lesion signs include:', '["Spasticity and Hyperreflexia", "Muscle atrophy, Fasciculations, and Hyporeflexia", "Babinski sign", "High muscle tone"]', 1, 'Matches the "Representativeness" for nerve or root damage.'),
    (v_topic_id, '334: "Upper Motor Neuron" (UMN) lesion signs include:', '["Atrophy", "Spasticity, Hyperreflexia, and Positive Babinski sign", "Fasciculations", "Hypotonia"]', 1, 'Indicates damage to the brain or spinal cord.'),
    (v_topic_id, '335: "Babinski Sign" (extension of the great toe and fanning of others) is normal in:', '["Adults", "Infants (up to ~1-2 years)", "The elderly", "Pregnant women"]', 1, 'In adults, it is a sign of UMN dysfunction (corticospinal tract).'),
    (v_topic_id, '336: "Hemisection" of the spinal cord results in:', '["Brown-S\u00e9quard Syndrome", "Cauda Equina Syndrome", "Syringomyelia", "Normal function"]', 0, 'Ipsilateral loss of motor/vibration and contralateral loss of pain/temp.'),
    (v_topic_id, '337: "Saddle Anesthesia" + "Loss of Bowel/Bladder control" is a neurosurgical emergency known as:', '["Conus Medullaris syndrome", "Cauda Equina Syndrome", "Sciatica", "Disc bulge"]', 1, 'Compression of the nerve roots at the end of the spinal canal.'),
    (v_topic_id, '338: "Tremor" that is "Resting" (worse at rest, better with movement) is classic for:', '["Essential Tremor", "Parkinson''s Disease", "Anxiety", "Hyperthyroidism"]', 1, 'Often described as "pill-rolling."'),
    (v_topic_id, '339: "Tremor" that is "Action/Intentional" (worse as the hand nears a target) is classic for:', '["Parkinson''s", "Cerebellar disease", "Normal", "Stroke"]', 1, 'Indicates dysfunction in the cerebellum or its pathways.'),
    (v_topic_id, '340: "Tremor" that is bilateral, high-frequency, and improved by alcohol is:', '["Parkinson''s", "Essential Tremor", "Withdrawal", "Stroke"]', 1, 'The most common movement disorder.'),
    (v_topic_id, '341: "Parkinsonism" is the triad of: Resting Tremor, Bradykinesia (slowness), and _____:', '["Weakness", "Rigidity (cogwheel)", "Atrophy", "Fever"]', 1, 'The fourth sign is postural instability.'),
    (v_topic_id, '342: "Rapidly Progressive Dementia" + "Myoclonus" (muscle jerks) should prompt evaluation for:', '["Alzheimer''s", "Creutzfeldt-Jakob Disease (CJD)", "Parkinson''s", "Stroke"]', 1, 'A prion disease.'),
    (v_topic_id, '343: "Normal Pressure Hydrocephalus" (NPH) triad: "Wet, Wacky, and _____":', '["Wild", "Wobbly (ataxic gait)", "Weak", "Worn-out"]', 1, 'Urinary incontinence, Dementia, and Gait instability.'),
    (v_topic_id, '344: "Huntington Disease" is characterized by progressive dementia and:', '["Rigidity", "Chorea (dance-like involuntary movements)", "Atrophy", "Seizures"]', 1, 'An autosomal dominant CAG repeat disorder.'),
    (v_topic_id, '345: "Multiple Sclerosis" (MS) is characterized by neurological deficits that are "disseminated in _____ and _____":', '["Time and Space", "Lungs and Heart", "Children and Adults", "Night and Day"]', 0, 'Multiple lesions in different locations occurring at different times.'),
    (v_topic_id, '346: "Lhermitte''s Sign" (electric shock sensation down the back on neck flexion) is seen in:', '["Stroke", "Multiple Sclerosis (indicating cervical cord involvement)", "Migraine", "Gout"]', 1, 'Also seen in other forms of cervical myelopathy.'),
    (v_topic_id, '347: "Uhthoff''s Phenomenon" in MS refers to the worsening of symptoms with:', '["Cold", "Heat (e.g., hot bath or exercise)", "Food", "Sleep"]', 1, 'Heat slows nerve conduction in demyelinated fibers.'),
    (v_topic_id, '348: "Bell''s Palsy" is an idiopathic palsy of the _____ nerve, causing _____:', '["Trigeminal; pain", "Facial (CN VII); complete unilateral facial weakness (including forehead)", "Abducens; double vision", "Vagus; hoarseness"]', 1, 'A stroke usually SPares the forehead because of bilateral cortical innervation.'),
    (v_topic_id, '349: "Ptosis" + "Miosis" + "Anhydrosis" is the triad for:', '["Graves disease", "Horner''s Syndrome", "Bell''s palsy", "Stroke"]', 1, 'Indicates a lesion along the sympathetic pathway to the eye.'),
    (v_topic_id, '350: "Clinical Reasoning" is a lifelong skill that is best improved by:', '["Reading one book", "Deliberate practice, seeking feedback, and constant reflection on one''s own thinking", "Ordering more tests", "Following rules strictly"]', 1, 'Balance System 1 intuition with System 2 analytical checking.');
